import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.PartyChanged{PartyInfo: protocol.Option(packet.PartyInfo{PartyID:
# "d1e2f3a4-5b6c-7d8e-9f01-234567890abc", PartyLeader: true})}
WITH_INFO = bytes.fromhex("012464316532663361342d356236632d376438652d396630312d32333435363738393061626301")

# generated by gophertunnel b8bd735:
# &packet.PartyChanged{}
ABSENT = bytes.fromhex("00")

# generated by gophertunnel b8bd735:
# &packet.PartyChanged{PartyInfo: protocol.Option(packet.PartyInfo{PartyID: "", PartyLeader: false})}
EMPTY_INFO = bytes.fromhex("010000")

GOLDENS = [
    pytest.param(
        v2225.PartyChangedPacket(
            party_info=v2225.PlayerPartyInfo(party_id="d1e2f3a4-5b6c-7d8e-9f01-234567890abc", is_leader=True)
        ),
        WITH_INFO,
        id="with-info",
    ),
    pytest.param(v2225.PartyChangedPacket(party_info=None), ABSENT, id="absent"),
    pytest.param(
        v2225.PartyChangedPacket(party_info=v2225.PlayerPartyInfo(party_id="", is_leader=False)),
        EMPTY_INFO,
        id="empty-info",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_party_changed_is_packet_342(version):
    assert version.PACKETS[342] is version.PartyChangedPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_party_changed_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_party_changed_decodes_from_its_golden(packet, golden):
    assert v2225.PartyChangedPacket.from_bytes(golden) == packet


def test_a_lone_true_byte_is_not_a_party_changed_body():
    with pytest.raises(ValueError, match="at byte"):
        v2225.PartyChangedPacket.from_bytes(WITH_INFO[:1])
